// Light / dark theme: the button next to the language switch.
//
// <html data-theme="dark"> switches the colours (css/dark.css, generated by
// scripts/build_dark_css.py, and css/dark-fixes.css). The choice is kept in
// the "theme" cookie for a year, so the server draws the next page in it
// right away; until it is chosen, the system setting decides (base.html).
(() => {
    'use strict';

    const COOKIE_MAX_AGE = 365 * 24 * 3600;
    const root = document.documentElement;

    function current() {
        return root.dataset.theme === 'dark' ? 'dark' : 'light';
    }

    function apply(theme) {
        // The new colours appear at once: hover transitions (board slots,
        // buttons, port tiles) would otherwise fade every element from one
        // theme to the other, unevenly while the board redraws.
        root.classList.add('theme-switching');
        root.dataset.theme = theme;
        document.cookie = `theme=${theme}; path=/; max-age=${COOKIE_MAX_AGE}; SameSite=Lax`;
        void root.offsetHeight;                    // apply the colours now, without transitions
        requestAnimationFrame(() => requestAnimationFrame(() => root.classList.remove('theme-switching')));
        // No redraw needed: cable lines and maps take their colours from CSS
        // classes, and the theme does not change any size.
    }

    document.addEventListener('click', event => {
        const button = event.target.closest && event.target.closest('[data-theme-toggle]');
        if (!button) return;
        event.preventDefault();
        apply(current() === 'dark' ? 'light' : 'dark');
    });
})();
